// =========================================================================\n// UNIDAD 3 - EJERCICIO 4: VENTANA METROWINDOW CON HAMBURGERMENU\n// =========================================================================\n// IMPORTANTE PARA EXAMEN:\n//   Cuando en el XAML usamos <mah:MetroWindow ...>, aquí en el .xaml.cs\n//   la clase DEBE heredar de ": MetroWindow" (y no de ": Window"),\n//   importando "using MahApps.Metro.Controls;".\n// =========================================================================\n\nusing Fluent;\nusing MahApps.Metro.Controls;\n\nnamespace di.unidad3.ejercicio4\n{\n    // Ejercicio de WPF. Esta clase representa la ventana principal del programa.\n    // En este archivo se inicializa la interfaz definida en XAML y se gestionan los eventos del formulario.\n    public partial class MainWindow : MetroWindow\n    {\n        // Constructor: se ejecuta al abrir la ventana y carga el contenido del archivo XAML.\n        public MainWindow()\n        {\n            InitializeComponent();\n        }\n    }\n}\n